package external

import saferis.*
import saferis.jdbc.JdbcSession
import saferis.jdbc.StandardJdbcAdapter
import saferis.tests.DatabaseTarget
import saferis.tests.SqlSessionConformance

import org.h2.jdbcx.JdbcDataSource
import zio.*
import zio.test.*

import javax.sql.DataSource

/** A database Saferis does not ship, brought from outside `package saferis` with only the public API: a `Dialect` for
  * the SQL, and a `JdbcAdapter` for the driver. H2 needs no adapter overrides at all, so this is the smallest case.
  */
object H2Dialect extends Dialect:
  val name: DialectName = DialectName("H2")

  def columnType(tpe: SqlType): ColumnType = ColumnType:
    tpe match
      case SqlType.Bool           => "boolean"
      case SqlType.Int2           => "smallint"
      case SqlType.Int4           => "integer"
      case SqlType.Int8           => "bigint"
      case SqlType.Float4         => "real"
      case SqlType.Float8         => "double precision"
      case SqlType.Numeric        => "decimal(38, 10)"
      case SqlType.VarChar        => s"varchar($DefaultVarcharLength)"
      case SqlType.Text           => "clob"
      case SqlType.Bytea          => "varbinary"
      case SqlType.Date           => "date"
      case SqlType.Time           => "time"
      case SqlType.Timestamp      => "timestamp"
      case SqlType.Timestamptz    => "timestamp with time zone"
      case SqlType.Jsonb          => "clob"
      case SqlType.Uuid           => "uuid"
      case SqlType.Array(element) => s"${columnType(element)} array"
      case SqlType.Other(_)       => "clob"

  def autoIncrementClause(isGenerated: Boolean, isPrimaryKey: Boolean, hasCompoundKey: Boolean): SqlText = SqlText:
    if isGenerated && isPrimaryKey && !hasCompoundKey then " generated by default as identity primary key"
    else if isGenerated then " generated by default as identity"
    else if isPrimaryKey && !hasCompoundKey then " primary key"
    else ""
end H2Dialect

object H2Adapter extends StandardJdbcAdapter

object BringYourOwnDatabaseSpecs extends ZIOSpecDefault:

  /** `DATABASE_TO_LOWER` folds unquoted names the way Postgres does, so a quoted `drop table` finds them. */
  private val dataSource: ULayer[DataSource] =
    ZLayer.succeed:
      val ds = JdbcDataSource()
      ds.setURL("jdbc:h2:mem:saferis_byo;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE")
      ds

  /** The portable core only: no catalog, no Postgres SQL, and no long statement to cancel. */
  private val target: ULayer[DatabaseTarget] = ZLayer.succeed(DatabaseTarget(H2Dialect))

  /** A database brought from outside `saferis` proves itself the same way the shipped ones do. */
  def spec =
    suite("h2, brought from outside saferis")(SqlSessionConformance.suite)
      .provideShared(dataSource >>> JdbcSession.layer(H2Adapter), target)
end BringYourOwnDatabaseSpecs
